import java.io.*;
import java.nio.file.*;

public class BufferedIODemo {
    public static void main(String[] args) throws IOException {
        var configFile = Path.of("application.properties");

        // Slow: unbuffered reading (1 system call per byte)
        try (var fis = new FileInputStream(configFile.toFile())) {
            int data;
            while ((data = fis.read()) != -1) {  // Each read() = 1 syscall
                // Process byte
            }
        }

        // Fast: buffered reading (1 syscall per 8KB chunk)
        try (var bis = new BufferedInputStream(
                new FileInputStream(configFile.toFile()))) {
            int data;
            while ((data = bis.read()) != -1) {  // Reads from memory buffer
                // Process byte - same API, 100x faster
            }
        }
    }
}

import java.io.*;
import java.nio.file.*;

public class FlushDemo {
    public static void writeConfigWithFlush(Path logFile) throws IOException {
        // Modern way: try-with-resources auto-flushes on close
        try (var writer = new BufferedWriter(new FileWriter(logFile.toFile()))) {
            writer.write("[INFO] Application started\n");
            writer.write("[INFO] Loading configuration\n");
            // No explicit flush needed - close() will flush automatically
        }  // close() called here, which calls flush() first
    }

    public static void streamingLog(BufferedWriter writer) throws IOException {
        writer.write("[INFO] Processing batch 1 of 10\n");
        writer.flush();  // Force write now so monitoring tools see progress

        // ... long-running work here ...

        writer.write("[INFO] Batch 1 complete\n");
        writer.flush();  // Flush again for real-time visibility
    }
}

import java.io.*;

public class CSVHeaderDetector {

    public boolean hasHeaderRow(File csvFile) throws IOException {
        try (var reader = new BufferedReader(new FileReader(csvFile))) {

            if (!reader.markSupported()) {  // Always check first
                throw new IOException("Stream doesn't support mark/reset");
            }

            reader.mark(1000);  // Remember position, buffer next 1000 chars

            var firstLine = reader.readLine();
            if (firstLine == null) return false;

            // Peek at second line to compare patterns
            var secondLine = reader.readLine();

            boolean hasHeader = looksLikeHeader(firstLine, secondLine);

            reader.reset();  // Return to beginning - first line is available again

            // Now we can process the file from the start with correct parsing logic
            return hasHeader;
        }
    }

    private boolean looksLikeHeader(String first, String second) {
        // Compare if first line has text while second has numbers
        return first != null && second != null && 
               first.matches(".*[a-zA-Z].*") && second.matches(".*\\d.*");
    }
}
